import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.1lR7qgqY.js";const b=JSON.parse('{"title":"第 20 章 安全公告與事件處理","description":"","frontmatter":{},"headers":[],"relativePath":"ops/20-advisories-incidents.md","filePath":"ops/20-advisories-incidents.md","lastUpdated":1793003170000}'),o={name:"ops/20-advisories-incidents.md"};function r(d,t,s,n,h,c){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="第-20-章-安全公告與事件處理" tabindex="-1">第 20 章 安全公告與事件處理 <a class="header-anchor" href="#第-20-章-安全公告與事件處理" aria-label="Permalink to &quot;第 20 章 安全公告與事件處理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 地端 AI 的事件多半從「更新時取得含惡意程式的版本」或「服務對外暴露」開始. 因此維運的重點是三件事: 知道公告, 能鎖定版本, 能快速輪替金鑰. 若不能每週檢查安全公告, 寧可少裝元件.</p><h2 id="_20-1-公告訂閱" tabindex="-1">20.1 公告訂閱 <a class="header-anchor" href="#_20-1-公告訂閱" aria-label="Permalink to &quot;20.1 公告訂閱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>管道</th><th>做法</th></tr></thead><tbody><tr><td>GitHub Security Advisories</td><td>在每個使用中元件的 GitHub 儲存庫訂閱安全通知 (操作介面可能調整, 請以 GitHub 官方文件為準)</td></tr><tr><td>元件發行頁</td><td>每週檢查一次安全公告; 升級前先讀發行說明</td></tr><tr><td>CISA Known Exploited Vulnerabilities (KEV)</td><td>每月比對一次使用中元件是否列入 (頻率為建議值, 屬推論)</td></tr><tr><td>本手冊<a href="/docs-handbook-poc/ref/versions">元件版本與安全公告頁</a></td><td>查看最後驗證日與已知問題</td></tr><tr><td>自家服務日誌</td><td>每週掃一次錯誤訊息; 位置與查看方式見<a href="/docs-handbook-poc/deploy/08-first-run">第 8.7 節</a></td></tr></tbody></table><h2 id="_20-2-案例-litellm-2026-年兩次供應鏈事件" tabindex="-1">20.2 案例: LiteLLM 2026 年兩次供應鏈事件 <a class="header-anchor" href="#_20-2-案例-litellm-2026-年兩次供應鏈事件" aria-label="Permalink to &quot;20.2 案例: LiteLLM 2026 年兩次供應鏈事件&quot;">​</a></h2><p>兩次事件的詳細時間線見<a href="/docs-handbook-poc/deploy/10-gateway">第 10.3 節</a>. 從維運角度可歸納三個教訓:</p><ol><li><strong>浮動標籤不可信</strong>: 2026-10-21 事件中, latest 與 main-stable 標籤都曾指向惡意映像 (LiteLLM 官方事故報告).</li><li><strong>事件起點常在上游的小疏失</strong>: 2026-03 事件起於 CI/CD 中未鎖定版本的掃描工具 (Snyk); 2026-10 事件起於 5 月有一組 master key 出現在公開儲存庫 (LiteLLM 官方攻擊鏈分析).</li><li><strong>風險集中於保存金鑰的服務</strong>: 閘道集中保存上游金鑰, 一旦入侵, 所有金鑰都須視為外洩.</li></ol><h2 id="_20-3-金鑰輪替與小團隊帳號管理" tabindex="-1">20.3 金鑰輪替與小團隊帳號管理 <a class="header-anchor" href="#_20-3-金鑰輪替與小團隊帳號管理" aria-label="Permalink to &quot;20.3 金鑰輪替與小團隊帳號管理&quot;">​</a></h2><h3 id="事件處理順序" tabindex="-1">事件處理順序 <a class="header-anchor" href="#事件處理順序" aria-label="Permalink to &quot;事件處理順序&quot;">​</a></h3><p>LiteLLM 兩次事件的官方建議都是「隔離, 重建, 輪替」:</p><ol><li><strong>隔離</strong>: 中斷受影響主機的對外網路, 停止相關容器.</li><li><strong>重建</strong>: 以已知安全的版本 (依官方公告指定) 重新建立容器與環境, 不在原主機上修補.</li><li><strong>輪替</strong>: 更換該主機上存放過的所有金鑰, 包含上游 API 金鑰與資料庫密碼.</li></ol><h3 id="事先準備" tabindex="-1">事先準備 <a class="header-anchor" href="#事先準備" aria-label="Permalink to &quot;事先準備&quot;">​</a></h3><ul><li>列出所有存放金鑰的位置 (<code>.env</code>, 閘道設定, 介面設定).</li><li>上游金鑰只給最低權限並設用量上限, 使外洩損失有上限.</li><li>演練一次輪替, 確認能在一小時內完成 (信心: 低, 此時間為建議目標, 非來源資料).</li></ul><h3 id="小團隊帳號" tabindex="-1">小團隊帳號 <a class="header-anchor" href="#小團隊帳號" aria-label="Permalink to &quot;小團隊帳號&quot;">​</a></h3><ul><li>每位使用者使用個別帳號, 並關閉公開註冊.</li><li>人員異動時, 當天停用帳號並檢視其持有的虛擬金鑰.</li><li>帳號清單每季檢視一次.</li></ul>',16)])])}const p=a(o,[["render",r]]);export{b as __pageData,p as default};
